#!/usr/bin/env node
/**
 * Bundles the custom hairline figures for pages without a bundler:
 *   node scripts/build_figures.mjs   →  examples/hairline-figures.js
 *
 * The output is one classic script (so the example page works when opened from disk, where
 * module imports are blocked) that sets `window.HairlineFigures`: the hairline engine (playground/hairline/kernel.js, the
 * package's src/core, unchanged), every figure in playground/hairline/figures/, and a
 * `mount(el, name, options)` that does what the skill's bench page does. Do not edit the
 * output; edit a figure and run this again.
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const dir = resolve(root, "playground/hairline");
const kernel = readFileSync(resolve(dir, "kernel.js"), "utf8").trimEnd();
// the kernel declares `var HL`; inside the IIFE that is a local, which is what the figures read
const figures = readdirSync(resolve(dir, "figures")).filter((f) => f.endsWith(".js")).sort();

const parts = [
  "/* Generated by scripts/build_figures.mjs from playground/hairline/{kernel.js,figures/*.js}. Do not edit. */",
  kernel,
  "(() => {",
  "const figures = new Map();",
  "const declare = (d) => figures.set(d.name, d);",
  ...figures.map((f) => `((hairline) => {\n${readFileSync(resolve(dir, "figures", f), "utf8").trim()}\n})(declare);`),
  readFileSync(resolve(root, "scripts/figures-mount.js"), "utf8").trim(),
  "})();",
];
const out = resolve(root, "examples/hairline-figures.js");
writeFileSync(out, parts.join("\n\n") + "\n");
console.log(`wrote ${out}: ${figures.map((f) => f.replace(".js", "")).join(", ")}`);
